import type { MainNavContextType } from "../main-nav.types";

import { useContext, createContext } from "react";

export type MainNavItemParentType = "menu" | "accordion" | undefined;

export const MainNavContext = createContext<MainNavContextType | undefined>(undefined);
export const useMainNav = () => {
  const context = useContext(MainNavContext);
  if (context === undefined) {
    throw new Error("useMainNav must be used within a <MainNav> component");
  }
  return context;
};

export const MainNavItemParentContext = createContext<MainNavItemParentType>(undefined);
export const useMainNavItemParent = () => {
  const context = useContext(MainNavItemParentContext);
  return context;
};
